      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "db43e253bea18.u21.5903",
            "quote": "Where a distributor highlights in an advertisement the financial return of its services, which is in fact derived from the actual return(s) of the underlying SFC-authorised fund(s), the advertisement, particularly the presentation of financial return relating to the services, should be prepared in a manner that is consistent with the principles under the SFC’s Advertising Guidelines Applicable to Collective Investment Schemes Authorized under the Product Codes4."
          },
          {
            "unit_id": "db43e253bea18.u30.8235",
            "quote": "4 As supplemented by the frequently asked questions and other guidance issued by the SFC from time to time."
          }
        ],
        "rationale": "The conditional SHOULD duty is expressly supported. Footnote 4 incorporates supplementary FAQs and guidance. The claim's statement that footnote 4 is not supplied is stale; the underlying external materials remain absent."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "992266faf576fb875514dcce2dc093509ff17576471836fad7b17e5bf08d265a",
        "evidence": [
          {
            "unit_id": "db43e253bea18.u13.2987",
            "quote": "Paragraph 3.11 of the Code of Conduct provides that distributors should not offer any gifts (other than a discount of fees or charges) in promoting a specific investment product or a particular type of investment product to a client."
          }
        ],
        "rationale": "The question concerns whether one component is caught by the gift restriction. Presentation of advertised service returns is a separate duty, even where the same promotion engages both."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [
          "Result: all of these conditions hold: [the fact component_is_gift; it is not the case that [the fact component_is_fee_or_charge_discount]; at least one of these conditions holds: [the fact component_promotes_specific_product; the fact component_linked_to_product_type]]"
        ],
        "rationale": "The executable result tests gift classification, the discount exception and promotional linkage. Its absence of advertising-presentation tests is not an omission relative to this typed question."
      },
      "authority": {
        "status": "MISSING",
        "dependency_ids": [],
        "rationale": "The Advertising Guidelines and their applicable supplementary FAQs and guidance are absent. No external dependency IDs are supplied. This prevents verification of their detailed requirements, not recognition of the circular's express duty."
      },
      "followup_questions": [
        "Can the applicable Advertising Guidelines and the supplementary FAQs and SFC guidance identified by footnote 4 be supplied, with their effective dates?"
      ]
    },
